package com.shopsphere;import jakarta.validation.constraints.*;import java.math.BigDecimal;import java.util.*;
public final class ProductDtos{private ProductDtos(){}public record Request(@NotBlank String sku,@NotBlank @Size(max=180)String name,@NotBlank String slug,@NotBlank String description,@NotBlank String brand,@NotBlank String category,@NotNull @DecimalMin("0.01")BigDecimal price,@NotNull @DecimalMin("0.01")BigDecimal originalPrice,@DecimalMin("0")@DecimalMax("100")BigDecimal discountPercentage,@DecimalMin("0")@DecimalMax("5")double rating,@PositiveOrZero long reviewCount,@NotEmpty List<@NotBlank String> imageUrls,Map<String,String> specifications,boolean active){}public record Page<T>(List<T> content,int page,int size,long totalElements,int totalPages){} }
